-- items: 13916
function event_combat(e)
	if(e.joined) then
		local cur_target = e.self:GetHateTop();
		if(cur_target) then
			e.self:Say(string.format("Time to die %s!",e.other:GetCleanName()));
		end
	end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Hail, " .. e.other:GetName() .. ". I am Deputy Budo Bullnose, the squad leader of the Great Wall Patrol. Be very careful in the lands beyond the wall. They are filled with dangerous beasts, as well as [" .. eq.say_link("Clan Runnyeye") .. "].");
	elseif(e.message:findi("clan Runnyeye")) then
		e.self:Say("Beyond this wall lies Runnyeye, the lair of the goblins of Clan Runnyeye. They have been a nuisance to Rivervale for quite some time. If you wish to join the fight, go to Rivervale and ask Sheriff Roglio about Clan Runnyeye.");
	elseif(e.message:findi("I am reporting for duty")) then
		e.self:Say("Stand tall then, Deputy " .. e.other:GetName() .. ". Your orders are to keep the creatures from venturing into the community of Rivervale and to kill many goblins. Check the goblin bodies, if you should find unbroken warrior beads on them, take them to Sheriff Roglio Bruth and should you be lucky enough to find a bizarre grappling device, you are to take it to Marshal Ghobber Truppack immediately! One more thing - should you defeat any orcs in battle, bring me their leather belts and I shall reward you for the great victory. May the power of Underfoot be with you!");
	end
end

function event_trade(e)
	local belt = 0;

	local item_lib = require("items");
	if(item_lib.check_turn_in(e.trade, {item1 = 13916, item2 = 13916, item3 = 13916, item4 = 13916})) then
		belt = 4;
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916, item2 = 13916, item3 = 13916})) then	
		belt = 3;
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916, item2 = 13916})) then
		belt = 2;
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916})) then
		belt = 1;
	end


	if(belt > 0) then
		repeat
		e.self:Say("Grand work. Deputy " .. e.other:GetName() .. "! You will become a full-fledged deputy in no time. You should check in with Marshal Ghobber from time to time to see if you have earned your squad ring. Just go up to him and ask. 'Am I one with the Wall?' He will know. but you must first show your bravery in many battles against the goblins.");
		e.other:Faction(263, 5); --Guardians of the Vale
		e.other:Faction(286, 1); --Mayor Gubbin
		e.other:Faction(355, 1); -- Storm Reapers
		e.other:Faction(292, 1); --Merchants of Rivervale
		e.other:Faction(334, -1); -- Dreadguard Outer
		e.other:QuestReward(e.self,0,0,9,0,13024,1000);
			belt = belt - 1;
		until belt == 0
	end		


	item_lib.return_items(e.self, e.other, e.trade)
end

-- items: 12369, 18746, 13507, 28055, 12344
function event_spawn(e)
	local xloc = e.self:GetX();
	local yloc = e.self:GetY();
	eq.set_proximity(xloc - 50, xloc + 50, yloc - 50, yloc + 50);
end

function event_enter(e)
	if(e.other:HasItem(18746)) then
		e.other:Message(MT.Yellow,"As you get your bearings, a lightly armored man that appears to be in incredible shape turns to greet you. 'Welcome traveller. I am Puab Closk. If you wish to learn the ways of the Ashen Order, read the note in your inventory and hand it to me to begin your training.'");
	end
end

function event_say(e)
	local fac = e.other:GetFaction(e.self);

	if(e.message:findi("hail")) then
		e.self:Say("Greetings. I am Puab Closk, Master of the Ashen Order.  Our home is your home, friend. Feel free to stay as long as you like.  Learn our ways as many have done in the past.  To fight like the tiger and strike like the cobra are your goals.");
	elseif(fac < 4) then
		if(e.message:findi("treant fists")) then
			e.self:Say("You desire the treant fists?  I have them and I will offer them to any [skilled monk of the Ashen House].");
		elseif(e.message:findi("who is clawfist ")) then
			e.self:Say("Clawfist is a Kerran, a catman. He braved the dangers of Norrath to reach the Ashen Order. He sought knowledge of our disiples. He learned well.");
		elseif(e.message:findi("where is clawfist")) then
			e.self:Say("Clawfist has been banished by the Kerrans of Odus. Where they have sent him I am unsure.");
		elseif(e.message:findi("skilled monk of the Ashen House")) then
			e.self:Say("Then you shall aid our family. My former pupil [Clawfist] has been banished by his people. You will go to him and hand him this token as proof of your origin. He shall be expecting you.");
			e.other:SummonItem(12369); -- Puab's Token
		end
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 18746})) then -- A tattered note
		e.self:Say("Welcome to the house of the Ashen Order. We are a small guild of monks who have devoted our lives to refining our minds, souls, and physical beings to their maximum potential. Please see Brother Torresk as soon as you get a chance. He is in charge of helping our newer members begin their training. Good luck, " .. e.other:GetName() .. ".");
		e.other:SummonItem(13507); -- Torn Cloth Tunic
		e.other:Ding();
		e.other:Faction(361,100,0); -- Ashen Order
		e.other:Faction(281,15,0); -- Knights of Truth
		e.other:Faction(309,5,0); -- Silent Fist Clan
		e.other:AddEXP(100);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 28055})) then -- Tattered Parchment
		e.self:Say("You have performed a great service to one who is your brother. Your loyalty shines brightly, as does your skill. Take the treant fists. They are yours now.");
		e.other:SummonItem(12344); -- Treant Fists
		e.other:Ding();
		e.other:Faction(361,10,0); -- Ashen Order
		e.other:Faction(281,5,0); -- Knights of Truth
		e.other:Faction(309,5,0); -- Silent Fist Clan
		e.other:AddEXP(100);
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

-- END of FILE Zone:freportw -- Puab_Closk

