	elseif((e.message:findi("interested") or (e.message:findi("deliver") and not e.message:findi("qeynos") and not e.message:findi("freeport")))) then
		e.self:Say("I have messages that need to go to Qeynos and to Freeport.  Will you [deliver] mail to [Qeynos] or [Freeport] for me?");
