	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 18707})) then -- Recruitment Flyer
		e.self:Say("Welcome to the Hall of Steel, our swords are strong, and our warriors stronger. Here is our guild tunic. Brin Stolunger is in charge of our new recruits. Go see him, and he'll teach the basics. You look like you'll make a fine addition to our guild. Once you are ready to pave your path to glory return to me for some initial armor quests.");
		e.other:SummonItem(13572); -- Dirty Training Tunic*
		e.other:Ding();
		e.other:Faction(311,100,0); -- Steel Warriors
		e.other:Faction(262,20,0); -- Guard of Qeynos
