	eq.stop_timer("emote")
	e.self:Emote("shakes with fear. A dark stain begins to spread across the front of his trousers. 'Ye.. Ye.. Yes.. Yes, Bruiser.");
	eq.signal(85226,51); -- NPC: Bruiser_Noz
end

