function event_signal(e)
	if e.signal==1 then
		e.self:Say("The spirits and heyokah call upon the greatness of Might. Turn your back on the way of the wasichu and return your steadfast spirit to us all.");
	end
end

--Hierophant Oxyn is for the Greenmist quest and is part of the eighth and final quest in the series. He also gives out the Cursed Wafer quest and shaman skullcaps 1 and 2.
-- items: 17020, 3895, 3886, 12403, 12721, 12722, 12723, 5140, 12724, 12725, 5141

function event_say(e)

	if(e.message:findi("hail")) then
		e.self:Say("Greetings, and may the pain of the ancients guide you. You have come to us for guidance, have you not? We are the Hierophants of Cabilis and we guide the young Scale Mystics. All petitioners shall speak with me of [temple tasks].");
	elseif((e.message:findi("temple tasks")) and (e.other:GetFaction(e.self) <= 4) and (e.other:Class() == "Shaman")) then
		e.self:Say("The Temple of Terror requires all young Scaled Mystics to [perform daily tasks.]. The tasks are necessary to the upkeep of our order as well as that of our brothers, the Crusaders of Greenmist.");
	elseif((e.message:findi("daily tasks")) and (e.other:GetFaction(e.self) <= 4) and (e.other:Class() == "Shaman")) then
		e.self:Say("We require many components for various rituals. Take this Component mortar and fill it with the following items - foraged [mud crabs]. two small mosquito wings and one portion of bone chips. You must then use the pestle and combine all the components. When you have a full component mortar, you may return to me and I shall pay you your wages, but most importantly, you shall prove your devotion to the Scaled Mystics.");
		e.other:SummonItem(17020); -- Component Mortar
	elseif(e.message:findi("mud crabs")) then 					--Cursed Wafers quest
		e.self:Say("Mud crabs are tiny crustaceans which live along the mudcaked shores of the Lake of Ill Omen. You can forage for them and find a handful of them at a time.");
	--Shaman Skull Quest No.1 Event_Say
	elseif((e.message:findi("lost skulls")) and (e.other:GetFaction(e.self) <= 4)) then
		e.self:Say("You must have heard of the Trilac Brotherhoods disappearance. They are the skulls of three soon to be ancients. They were taken from this temple by a silent intruder. Crusaders are always on duty. I do not know how they got into our vault. Every petitioner is ordered to search for the three skulls and return them to me along with their petitioner cudgel and then they shall become clairvoyants.");
	elseif(e.message:findi("iron cudgel")) then
		if (e.other:GetFaction(e.self) <= 4) then
			e.self:Emote("shakes his head and waves a finger in your face. If you are looking to be handed the Iron Cudgel of the Clairvoyant then you are sadly mistaken. Perhaps if you were to gather a few [lost skulls] for the temple we may find you worthy to wield one.'");
		else
			e.self:Say("If you are looking to be handed the Iron Cudgel of the Clairvoyant then you are sadly mistaken. Perhaps if you were to gather a few [lost skulls] for the temple we may find you worthy to wield one.");
		end
	--Shaman Skull Quest No.2 Event_Say
	elseif((e.message:findi("larger problem")) and (e.other:GetFaction(e.self) <= 4)) then
		e.self:Say("Many of the ancient skulls have been cast out of our temple. A hierophant was supposed to cast a special spell which was to protect the skulls from dust and decay. He cast some unknown spell which has sent many of our skulls to their original point of death. It would be most helpful if you would [assist in collecting the ancient skulls].");
	elseif((e.message:findi("ancient skull")) and (e.other:GetFaction(e.self) <= 4)) then
		e.self:Emote("seems unsure of your prowess. 'Hmmm. First you shall go after the two skulls of the Cleansers of the Outlands. If you find them, bring them back unbroken and then I shall trust you. Hand me both skulls and your iron cudgel of the clairvoyant and I will know you are prepared.'");
	elseif(e.message:findi("liquid")) then 						--Crusaders of Greenmist (Greenmist Quest 8/8)
		e.self:Say("The bottle contains deklium in a liquid solution. The metal of prophecy has been determined to rest in a mass of living earth. Our scholars have written of a mass of ore that fell from the heavens. This ore was used in the creation of a blade of our father, Rile. We have been filled with visions of this blade. I have seen it in the hands of our Crusaders as they march towards the new age of Greenmist! Seek out the corrupted earth that guards the interlopers. We have an alchemist near there. He will be able to use the deklium to determine which golem contains the metal. Take care to go in force. I sense that there will be a battle.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(e.other:GetFaction(e.self) < 5 and item_lib.check_turn_in(e.trade, {item1 = 3895})) then 	--Crusaders of Greenmist (Greenmist Quest 8/8)
		e.self:Emote("takes the note and begins to howl into the air! 'The visions are true! The new prophecy begins today, Crusader,' the mystic growls with pleasure. He quickly turns and takes a bottle of murky liquid from one of his potion bags and hands it to you. 'Take this and keep it safe. Our visions have told of this day. We have been able to learn of the metal of prophecy. This [liquid] will help us to locate its true resting place!");
		e.other:Faction(442,20); -- Faction: Crusaders of Greenmist
		e.other:Faction(441,10); -- Faction: Legion of Cabilis
		e.other:QuestReward(e.self,0,0,0,0,3892,5000); --Bottle of Liquid Deklium
	elseif(e.other:GetFaction(e.self) < 5 and item_lib.check_turn_in(e.trade, {item1 = 3886})) then --Crusaders of Greenmist (Greenmist Quest 8/8)
		e.self:Emote("holds the ore in his hands and begins to chant. His eyes go white as he raises the chunk of ore above his head. He lowers his arms and shakes his head for a moment. His eyes return to their normal state as they focus on you. The shaman hands you the ore and says, 'Seek out the creator of Rile's blade. He is still on this plane. I have felt his torment. Take this note to Librarian Zimor. He learned a great deal from the tome and can instruct you further.'");
		e.other:Faction(442,20); -- Faction: Crusaders of Greenmist
		e.other:Faction(441,10); -- Faction: Legion of Cabilis
		e.other:QuestReward(e.self,{items = {3893,3886}, exp = 5000}); -- Items: Note to Librarian, Chunk of Tynnonium

	--Cursed Wafers turn in
	elseif(e.other:GetFaction(e.self) < 5 and e.other:Class() == "Shaman" and item_lib.check_turn_in(e.trade, {item1 = 12403})) then --Full Component Mortar
		e.self:Say("We appreciate your service. Take a few copper for your deed as well as some of our cursed waters. They will provide you with nourishment. As for future tasks, we are searching for a few [lost skulls] and i am sure you are searching for your [iron cudgel of the clairvoyant] And i also hear that the furscales are in need of some broodlings to do some manual labor. Tell them Oxyn sent you.");
		e.other:Faction(445, 2); 				--Scaled Mystics
		e.other:Faction(441, 1); 				--Legion of Cabilis
		e.other:QuestReward(e.self,{items = {12406,12406}, exp = 50}); -- Items: Cursed Wafers 2x
	--Shaman Skull Quest No.1 turn in - Check for  Logrin Skull, Morgl Skull, and Waz Skull hand in along with Iron Cudgel of the Petitioner
	elseif(e.other:GetFaction(e.self) <= 4 and item_lib.check_turn_in(e.trade, {item1 = 12721, item2 = 12722, item3 = 12723, item4 = 5140})) then
		e.self:Say("Excellent! You have proved yourself worthy to wield the iron cudgel of the clairvoyant. As a clairvoyant I feel I can trust you, so I will tell you that the issue of the missing skulls is a [much larger problem] than last stated.");
		e.other:Faction(445, 10); 				--Scaled Mystics
		e.other:Faction(441, 5); 				--Legion of Cabilis
		e.other:QuestReward(e.self,0,0,0,1,5141,2000); --Iron Cudgel of the Clairvoyant
	--shaman skull quest no.2 turn in - check for Skull with I and Skull with II turn in and cudgel
	elseif(e.other:GetFaction(e.self) <= 4 and item_lib.check_turn_in(e.trade, {item1 = 12724, item2 = 12725, item3 = 5141})) then
		e.self:Say("We are in your debt," .. e.other:GetCleanName() .. " . You are truly one who shall collect all the lost ancient skulls. Take your weapon. Go to Hierophant Zand and he shall guide you further. Tell him you are [the chosen saviour].");
		e.other:Faction(445, 10); 				--Scaled Mystics
		e.other:Faction(441, 5); 				--Legion of Cabilis
		e.other:QuestReward(e.self,0,0,5,1,5142,60000); --Iron Cudgel of the Seer
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

-- items: 52964, 54289
function event_trade(e)
	local item_lib = require("items");
	local qglobals = eq.get_qglobals(e.other);
	if(qglobals["ench_epic"] ~= nil and qglobals["ench_epic"] >= "2" and e.other:GetFaction(e.self) < 5) then	
		if(item_lib.check_turn_in(e.trade, {item1 = 52964})) then		
			e.self:Say("I can't . . I . . .of course, I do not think that Tserrina has any need for this. I can't imagine that she would miss it at all. Please, take it.");
			e.other:SummonItem(54289); -- Item: 1st Piece of the Staff
		end
	end	
	item_lib.return_items(e.self, e.other, e.trade)
end

-- items: 19555, 19558, 19559, 19561, 19557, 19560, 19556, 19627, 17124
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("I am busy right now. Please leave me alone."); --Text made up
	elseif(e.message:findi("thorn mail coif")) then
		e.self:Say("To assemble a Thorn Mail Coif you will require two [silk thread], ruined thorn drakeling scales, and a giant thicket rat skull. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Coif Pattern.");
		e.other:SummonItem(19555,1); -- Item: Tattered Cap Pattern
	elseif(e.message:findi("thorn mail bracer")) then
		e.self:Say("To assemble a Thorn Mail Bracer you will require a [silk thread], ruined thorn drakeling scales, and a large fruit bat wing. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Bracer Pattern.");
		e.other:SummonItem(19558,1); -- Item: Tattered Wristband Pattern
	elseif(e.message:findi("thorn mail gloves")) then
		e.self:Say("To assemble Thorn Mail Gloves you will require two [silk thread], ruined thorn drakeling scales, and two large fruit bat furs. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Glove Pattern.");
		e.other:SummonItem(19559,1); -- Item: Tattered Glove Pattern
	elseif(e.message:findi("thorn mail boots")) then
		e.self:Say("To assemble Thorn Mail Boots you will require two [silk thread], two ruined thorn drakeling scales, and two giant thicket rat pelts. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Boot Pattern.");
		e.other:SummonItem(19561,1); -- Item: Tattered Boot Pattern
	elseif(e.message:findi("thorn mail sleeves")) then
		e.self:Say("To assemble Thorn Mail Sleeves you will require two [silk thread], thorn drakeling scales, and two giant fruit bat wings. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Sleeves Pattern.");
		e.other:SummonItem(19557,1); -- Item: Tattered Sleeve Pattern
	elseif(e.message:findi("thorn mail leggings")) then
		e.self:Say("To assemble Thorn Mail Leggings you will require three [silk thread], two thorn drakeling scales. and two giant fruit bat furs. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Leggings Pattern.");
		e.other:SummonItem(19560,1); -- Item: Tattered Pant Pattern
	elseif(e.message:findi("thorn mail tunic")) then
		e.self:Say("To assemble a Thorn Mail Tunic you will require four [silk thread], pristine thorn drakeling scales, a giant fruit bat rib cage, and a giant fruit bat fur. Once you have the necessary components combine them in your Mail Assembly Kit with this Tattered Tunic Pattern.");
		e.other:SummonItem(19556,1); -- Item: Tattered Tunic Pattern
	elseif(e.message:findi("silk thread")) then
		e.self:Say("To make silk thread, take 2 spiderling silks and combine them together in a loom or in your handy sewing kit."); --Text made up
	end
end

function event_trade(e)
local item_lib = require("items");

	if (item_lib.check_turn_in(e.trade,  {item1 = 19627})) then
		e.self:Say(string.format("Pleased to meet you %s! You must be one of Megosh's new trainees. Megosh has asked me to help get you outfitted in a suit of armor to protect you from the vile weapons of Rivervales foes. I have assembled a kit for you that will allow you to construct the armor pieces once you have gathered the necessary components. The required components vary according to which piece of Thorn Mail armor you are planning on assembling. Do you wish to craft a [thorn mail coif], a [thorn mail bracer], [thorn mail gloves], [thorn mail boots], [thorn mail sleeves], [thorn mail leggings], or a [thorn mail tunic].", e.other:GetCleanName()));
		e.other:SummonItem(17124); -- Item: Mail Assembly Kit
	else
		item_lib.return_items(e.self, e.other, e.trade);
	end
end
--END of FILE Zone:rivervale  ID:19046 -- Bipdo_Hargin

-- items: 18934, 18814
function event_say(e)
	local fac = e.other:GetFaction(e.self);

	if(e.message:findi("hail")) then
		e.self:Say("Greetings " .. e.other:GetName() .. ", and welcome to the Bunker. Are you a [new warrior] or [veteran]?");
	elseif(e.message:findi("Milea")) then
		e.self:Say("Milea Clothspinner. She was my one true love. She, too, is a Steel Warrior. When she left Qeynos to find adventure, my heart left also. I never saw her again, but I decided to transfer my skills to Freeport. It is probably best that I did not find her. She was in love with adventure. sigh> The women I am attracted to are always in love with another. Just like [Toala].");
	elseif(e.message:findi("Toala")) then
		e.self:Say("Toala is supreme when it comes to the blade, but in the art of passion she chooses to leans toward Cain Darkmoore. I do not get it. She is a very beautiful and strong-hearted warrior. Why Cain does not like her is a mystery to me. Why does she waste her time when she could have me? After all, we men of Qeynos are known as the most romantic in all of Norrath.");
	elseif(e.message:findi("milea is in east karana")) then
		e.self:Say("You have seen Milea Clothspinner!! This is great news. I wish I could travel to see her, but Cain will not allow me to do so at this time. You must take her a note for me. Here, take this to her. As a master in this order, I command you to do so immediately. Go!!");
		e.other:SummonItem(18934); -- A Sealed Letter ID- 18934 - 'LoveToMilea'
	elseif(fac < 5) then
		if(e.message:findi("new warrior")) then
			e.self:Say("Good to know you chose the Bunker to train you. It is the home of The Steel Warriors. We find our inner strengths grow through battles and deeds to further our growth. Do you [seek deeds] or [crave battle]?");
		elseif(e.message:findi("seek deeds")) then
			e.self:Say("It may not be a fray, but who ever said we Steel Warriors are nothing but brawn?  Recently, there has been reports of frequent visits by dark elves to the Hog Caller's Inn, here in Freeport. Go speak with Lady Shae. Tell her, the [Steel Warriors sent you]. We cannot rely on the Freeport Militia to look into such matters. They are probably involved. Bring me any clues you find.");
		elseif(e.message:findi("crave battle")) then
			e.self:Say("Aye!!  That is good.  Ask Cain Darkmoore about Clan Deathfist.  Also, when striking underhand, plant your feet at shoulder width and push with your legs on contact.  It does wonders and keeps your back and shoulders from aching.");		
		elseif(e.message:findi("veteran")) then
			e.self:Say("I apologize for not knowing. I am new to the Bunker. I was a trainer at the Hall of Steel in Qeynos before this.  I left Qeynos in search of [Milea] and instead found myself joining the bunker's weaponmasters.");
		end
	elseif(fac == 5) then
		if(e.message:findi("new warrior") or e.message:findi("seek deeds") or e.message:findi("crave battle") or e.message:findi("veteran")) then
			e.self:Say("The Steel Warriors have no cause to dislike you, but you have yet to prove your worth to this guild.");
		end
	elseif(fac > 5) then
		if(e.message:findi("new warrior") or e.message:findi("seek deeds") or e.message:findi("crave battle") or e.message:findi("veteran")) then
			e.self:Say("Your head shall look grand mounted on the wall of the Steel Warriors Arena!!");
		end
	end
end

function event_trade(e)
	local item_lib = require("items");
	local fac = e.other:GetFaction(e.self);

	if(fac < 5) then
		if(item_lib.check_turn_in(e.trade, {item1 = 18814})) then -- A Sealed Letter ID-18814 filename "NERtoShintl"
			e.self:Say("Oh my! Opal? She is providing these agents of Neriak with information regarding the Acedemy's secrets. I can not tell Cain about this. He will be furious. Show this to Toala. She will know what to do.");
			e.other:SummonItem(18814); -- A Sealed Letter ID-18814 filename "NERtoShintl"
		end
	elseif(fac == 5) then
		if(item_lib.check_turn_in(e.trade, {item1 = 18814})) then-- A Sealed Letter ID-18814 filename "NERtoShintl"  Item will be lost if not amiable or better
			e.self:Say("The Steel Warriors have no cause to dislike you, but you have yet to prove your worth to this guild.");
		end
	elseif(fac > 5) then
		if(item_lib.check_turn_in(e.trade, {item1 = 18814})) then-- A Sealed Letter ID-18814 filename "NERtoShintl"  Item will be lost if not amiable or better
			e.self:Say("Your head shall look grand mounted on the wall of the Steel Warriors Arena!!");
		end
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

