		e.self:Say("Thank you " .. e.other:GetName() .. ". I had no doubt you would fulfill my will and return my spellbook.. here is your reward for such effort. Now I have news of a larger matter. It has to do with a [defector].");
		e.other:Faction(245,3,0); -- Eldritch Collective
		e.other:Faction(238,-3,0); -- Dark Reflection
		e.other:Faction(239,-3,0); -- The Dead
		e.other:Faction(255,3,0); -- Gem Choppers
		e.other:Faction(333,3,0); -- King Ak`Anon
		e.other:Ding();
		e.other:AddEXP(150);
