		e.other:Faction(238,-3,0); -- Dark Reflection
		e.other:Faction(239,-3,0); -- The Dead
		e.other:Faction(255,3,0); -- Gem Choppers
		e.other:Faction(333,3,0); -- King Ak`Anon
		e.other:Ding();
